// head_a skin: everything here is generated by our own code.
//  - per-vertex tint / cavity colours and skin data (roughness, pore strength, stubble, thinness) from
//    landmark-anchored region fields (cheek and nose flush, beard shadow, lips, periorbital tone ...)
//  - shared tileable detail maps made once per session: a 1024px pore / furrow normal map and a
//    mottling / stubble map
//  - per-head feature maps drawn in UV space: brows, lash lines, freckles, moles, scar, and a wrinkle
//    height field (forehead, frown, crow's feet, under-eye, lip, neck lines) converted to a normal map
//  - a MeshPhysicalMaterial with an injected subsurface approximation (per-channel wrap lighting with a
//    reddish terminator, softened diffuse normal, thin-tissue transmission), detail-normal blending and
//    per-vertex roughness.
import * as THREE from 'three';
import { clamp, lerp, sstep, mulberry32 } from './head_a_util.js';

const s2l = (c) => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));
const hexLin = (h) => [s2l(((h >> 16) & 255) / 255), s2l(((h >> 8) & 255) / 255), s2l((h & 255) / 255)];
const g2 = (u, v) => Math.exp(-(u * u + v * v));

function makeCanvas(w, h) {
  if (typeof document !== 'undefined' && document.createElement) { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; }
  const OC = globalThis.OffscreenCanvas;
  return OC ? new OC(w, h) : null;
}

// ------------------------------------------------------------------ per-vertex data
export function skinVertexData(D, P) {
  const F = D.F, NV = D.NV, S = D.S;
  const pos = D.P0; // reference space
  const RL = D.relief;
  const base = hexLin(P.skin);
  const lumB = base[0] * 0.2126 + base[1] * 0.7152 + base[2] * 0.0722;
  const dark = 1 - sstep(0.06, 0.4, lumB);     // 1 = deep skin tone
  const masc = F.masc, old = F.old;
  // absolute target colours (linear)
  const lipCol = [base[0] * lerp(0.86, 0.78, dark), base[1] * lerp(0.50, 0.58, dark), base[2] * lerp(0.50, 0.64, dark)];
  const mouthIn = [0.09, 0.022, 0.02];
  const wetLid = [base[0] * 0.95, base[1] * 0.62, base[2] * 0.62];
  const col = new Float32Array(NV * 3), dat = new Float32Array(NV * 4);
  // cavity: concavity from a two-ring Laplacian of the neutral mesh
  const idx = D.index;
  const nb = new Float64Array(NV * 3), cnt = new Float32Array(NV);
  for (let k = 0; k < idx.length; k += 3) for (let e = 0; e < 3; e++) {
    const a = idx[k + e], b = idx[k + (e + 1) % 3];
    nb[a * 3] += pos[b * 3]; nb[a * 3 + 1] += pos[b * 3 + 1]; nb[a * 3 + 2] += pos[b * 3 + 2]; cnt[a]++;
    nb[b * 3] += pos[a * 3]; nb[b * 3 + 1] += pos[a * 3 + 1]; nb[b * 3 + 2] += pos[a * 3 + 2]; cnt[b]++;
  }
  const nrm = D.normals;
  const cav = new Float32Array(NV);
  for (let i = 0; i < NV; i++) {
    if (!cnt[i]) continue;
    const dx = nb[i * 3] / cnt[i] - pos[i * 3], dy = nb[i * 3 + 1] / cnt[i] - pos[i * 3 + 1], dz = nb[i * 3 + 2] / cnt[i] - pos[i * 3 + 2];
    cav[i] = (dx * nrm[i * 3] + dy * nrm[i * 3 + 1] + dz * nrm[i * 3 + 2]) / S;
  }
  // smooth the cavity a little (neighbour average) so it reads as soft occlusion
  const cav2 = new Float32Array(NV);
  {
    const acc = new Float32Array(NV), c2 = new Float32Array(NV);
    for (let k = 0; k < idx.length; k += 3) for (let e = 0; e < 3; e++) { const a = idx[k + e], b = idx[k + (e + 1) % 3]; acc[a] += cav[b]; c2[a]++; acc[b] += cav[a]; c2[b]++; }
    for (let i = 0; i < NV; i++) cav2[i] = 0.5 * cav[i] + 0.5 * (c2[i] ? acc[i] / c2[i] : 0);
  }
  const eyes = D.eyes;
  const mw = F.mouthW, yS = F.ySub, yT = F.yTip, ySl = F.ySlit;
  for (let i = 0; i < NV; i++) {
    const x = pos[i * 3], y = pos[i * 3 + 1], z = pos[i * 3 + 2];
    const ax = Math.abs(x);
    const tag = D.tag[i];
    let r = 1, g = 1, b = 1;
    const tint = (t, s) => { r *= lerp(1, t[0], s); g *= lerp(1, t[1], s); b *= lerp(1, t[2], s); };
    const front = sstep(-0.01, 0.04, z);
    // flush: cheeks, nose tip / alae, chin, forehead, ears handled by the ear mesh
    const cheek = g2((ax - 0.041) / 0.019, (y - F.yEye + 0.031) / 0.017) * front;
    const nose = (ax < 0.024 ? g2(x / 0.016, (y - yT + 0.004) / 0.012) : 0) * sstep(0.095, 0.105, z);
    const chin = g2(x / 0.016, (y - F.yPog) / 0.012) * front;
    const fore = g2(x / 0.03, (y - F.yBrow - 0.03) / 0.02) * front;
    const flush = clamp((0.42 + 0.22 * F.fem + 0.25 * F.child) * cheek + 0.55 * nose + 0.22 * chin + 0.08 * fore, 0, 1) * (1 - 0.45 * dark);
    tint([1.13, 0.86, 0.84], flush);
    // T-zone a touch more yellow / olive, under the jaw and neck a little paler
    tint([1.03, 1.0, 0.9], g2(x / 0.02, (y - F.yBrow - 0.01) / 0.03) * 0.5 * front);
    tint([1.02, 1.03, 1.04], sstep(-0.01, -0.06, y) * 0.6);
    // periorbital: thin, slightly darker, cooler skin around the eyes
    for (const E of eyes) {
      const L = E.lids;
      const u = L.side * (x - L.E[0]) / 0.001, v = (y - L.E[1]) / 0.001;
      const under = g2((u - 1) / 13, (v + 9.5) / 4.5), upper = g2((u + 1) / 14, (v - 8) / 6);
      tint([0.86, 0.80, 0.84], (0.5 + 0.4 * old + 0.2 * dark) * under * front);
      tint([0.95, 0.86, 0.86], 0.45 * upper * front);
    }
    // beard / stubble zone (male): jaw, chin, upper lip, lower cheeks, under the jaw
    let beard = 0;
    if (masc > 0.05) {
      const yLine = lerp(F.ySub + 0.006, F.yEye - 0.018, sstep(0.02, 0.064, ax));
      beard = sstep(yLine + 0.004, yLine - 0.006, y) * sstep(-0.085, -0.06, y) * sstep(-0.026, -0.006, z);
      beard *= 1 - (ax < 0.022 && y > yS - 0.003 ? 1 : 0) * sstep(yS - 0.003, yS + 0.001, y);
      beard *= 1 - 0.85 * g2(ax / 0.006, (y - ySl + F.tl + 0.006) / 0.004) * 0; // (soul patch kept)
      beard = clamp(beard, 0, 1) * masc;
    }
    const lipW = D.lip[i];
    beard *= 1 - lipW;
    tint([0.80, 0.83, 0.90], beard * (0.35 + 0.65 * P.marks.stubble) * (1 - 0.5 * dark));
    // lips
    if (lipW > 0) {
      const t = [lipCol[0] / base[0], lipCol[1] / base[1], lipCol[2] / base[2]];
      // fuller centre of the lower lip slightly lighter, corners darker
      const c = 1 - 0.18 * sstep(0.6, 1.0, ax / mw);
      tint([t[0] * c, t[1] * c, t[2] * c], lipW);
    }
    // eyelid margins and openings
    const lr = D.lidRing[i];
    if (lr === 2) tint([wetLid[0] / base[0], wetLid[1] / base[1], wetLid[2] / base[2]], 1);
    else if (lr === 3) tint([0.25, 0.12, 0.12], 1);
    else if (lr === 1) tint([0.9, 0.78, 0.78], 0.6);
    // mouth interior
    if (tag === 3) { r = mouthIn[0] / base[0]; g = mouthIn[1] / base[1]; b = mouthIn[2] / base[2]; }
    // scalp a little paler, back of the neck a little darker
    tint([1.03, 1.02, 1.0], sstep(0.16, 0.19, y) * 0.5);
    // cavity occlusion
    const cv = Math.max(0, cav2[i]);
    const occ = clamp(1 - cv * 260, 0.42, 1) * (tag === 3 ? 1 : 1);
    // nostril pockets darker still
    const nosD = (ax < 0.02 && y > yS - 0.002 && y < yS + 0.009) ? g2((ax - RL.nostril.c[0]) / (RL.nostril.r[0] * 1.15), (y - RL.nostril.c[1]) / (RL.nostril.r[1] * 1.3)) : 0;
    const o = occ * (1 - 0.72 * nosD);
    col[i * 3] = r * lerp(o, 1, 0.12); col[i * 3 + 1] = g * o; col[i * 3 + 2] = b * o;
    // roughness, pores, stubble, thinness
    let rough = 0.5;
    rough = lerp(rough, 0.40, g2(x / 0.03, (y - F.yBrow - 0.02) / 0.03) * front);       // forehead
    rough = lerp(rough, 0.35, nose);                                                      // nose
    rough = lerp(rough, 0.44, chin);
    rough = lerp(rough, 0.30, lipW);
    if (lr === 1 || lr === 2) rough = 0.22;
    rough = lerp(rough, 0.58, beard * P.marks.stubble);
    if (tag === 3) rough = 0.3;
    let pore = 0.55;
    pore = lerp(pore, 1.0, nose); pore = lerp(pore, 0.9, cheek); pore = lerp(pore, 0.75, chin);
    pore *= (1 - lipW) * (D.lidLam[i] >= 0 ? sstep(0.2, 1.6, D.lidLam[i]) * 0.8 + 0.2 : 1);
    pore *= 1 - 0.5 * sstep(-0.02, -0.07, y);
    pore *= lerp(1, 0.55, F.child) * lerp(1, 0.8, F.young);
    const thin = clamp(0.8 * nose + 0.6 * lipW + 0.4 * g2(x / 0.01, (y - yS + 0.002) / 0.01) * 0, 0, 1);
    dat[i * 4] = rough; dat[i * 4 + 1] = pore; dat[i * 4 + 2] = beard * P.marks.stubble; dat[i * 4 + 3] = thin;
  }
  return { color: col, data: dat, base };
}

// ------------------------------------------------------------------ shared tileable detail maps
let DETAIL = null;
function heightToNormal(h, W, H, strength, wrap, rowsUp) {
  const out = new Uint8Array(W * H * 4);
  for (let j = 0; j < H; j++) {
    const jm = wrap ? (j - 1 + H) % H : Math.max(0, j - 1), jp = wrap ? (j + 1) % H : Math.min(H - 1, j + 1);
    for (let i = 0; i < W; i++) {
      const im = wrap ? (i - 1 + W) % W : Math.max(0, i - 1), ip = wrap ? (i + 1) % W : Math.min(W - 1, i + 1);
      const dx = (h[j * W + ip] - h[j * W + im]) * strength;
      const dy = (rowsUp ? h[jp * W + i] - h[jm * W + i] : h[jm * W + i] - h[jp * W + i]) * strength;
      const l = Math.sqrt(dx * dx + dy * dy + 1);
      const k = (j * W + i) * 4;
      out[k] = (-dx / l * 0.5 + 0.5) * 255; out[k + 1] = (-dy / l * 0.5 + 0.5) * 255; out[k + 2] = (1 / l * 0.5 + 0.5) * 255; out[k + 3] = 255;
    }
  }
  return out;
}
export function detailMaps() {
  if (DETAIL) return DETAIL;
  const R = mulberry32(90210);
  const NS = 1024;
  let normalTex, detailTex;
  const cv = makeCanvas(NS, NS);
  if (cv) {
    const g = cv.getContext('2d', { willReadFrequently: true });
    g.fillStyle = 'rgb(128,128,128)'; g.fillRect(0, 0, NS, NS);
    const wrapDraw = (x, y, rad, fn) => { for (const ox of [-NS, 0, NS]) for (const oy of [-NS, 0, NS]) { if (x + ox < -rad || x + ox > NS + rad || y + oy < -rad || y + oy > NS + rad) continue; fn(x + ox, y + oy); } };
    // skin furrows: a network of fine creases
    g.lineCap = 'round';
    for (let k = 0; k < 2600; k++) {
      const x = R() * NS, y = R() * NS, a = (R() < 0.5 ? 0.7 : -0.7) + (R() - 0.5) * 0.9, len = 6 + R() * 22;
      const c = 92 + R() * 25;
      wrapDraw(x, y, len, (px, py) => { g.strokeStyle = `rgba(${c},${c},${c},0.55)`; g.lineWidth = 0.9 + R() * 0.8; g.beginPath(); g.moveTo(px, py); g.lineTo(px + Math.cos(a) * len, py + Math.sin(a) * len); g.stroke(); });
    }
    // pores: small dimples on a jittered grid
    const step = 11;
    for (let j = 0; j < NS / step; j++) for (let i = 0; i < NS / step; i++) {
      const x = (i + R()) * step, y = (j + R()) * step, rr = 0.9 + R() * 1.5, c = 40 + R() * 50;
      wrapDraw(x, y, 4, (px, py) => { g.fillStyle = `rgba(${c},${c},${c},0.85)`; g.beginPath(); g.arc(px, py, rr, 0, Math.PI * 2); g.fill(); });
    }
    // small raised bumps
    for (let k = 0; k < 1800; k++) {
      const x = R() * NS, y = R() * NS, rr = 1.2 + R() * 2.2, c = 150 + R() * 30;
      wrapDraw(x, y, 4, (px, py) => { g.fillStyle = `rgba(${c},${c},${c},0.35)`; g.beginPath(); g.arc(px, py, rr, 0, Math.PI * 2); g.fill(); });
    }
    const img = g.getImageData(0, 0, NS, NS).data;
    // soft blur (3x3) with wrap, to height
    const h0 = new Float32Array(NS * NS), h = new Float32Array(NS * NS);
    for (let k = 0; k < NS * NS; k++) h0[k] = img[k * 4] / 255;
    for (let j = 0; j < NS; j++) for (let i = 0; i < NS; i++) {
      let s = 0;
      for (let dj = -1; dj <= 1; dj++) for (let di = -1; di <= 1; di++) s += h0[((j + dj + NS) % NS) * NS + ((i + di + NS) % NS)] * (di === 0 && dj === 0 ? 4 : di === 0 || dj === 0 ? 2 : 1);
      h[j * NS + i] = s / 16;
    }
    const nd = heightToNormal(h, NS, NS, 3.2, true, true);
    normalTex = new THREE.DataTexture(nd, NS, NS);
    // mottling (R), redness (G), roughness variation (B), stubble field (A)
    const DS = 512;
    const c2 = makeCanvas(DS, DS);
    const q = c2.getContext('2d', { willReadFrequently: true });
    q.fillStyle = 'rgba(128,128,128,0)'; q.clearRect(0, 0, DS, DS);
    const dImg = q.createImageData(DS, DS);
    const d = dImg.data;
    // value noise helpers on a wrapped lattice
    const lat = (n, seed) => { const r = mulberry32(seed); const a = new Float32Array(n * n); for (let k = 0; k < n * n; k++) a[k] = r(); return a; };
    const L1 = lat(16, 3), L2 = lat(48, 5), L3 = lat(32, 7), L4 = lat(96, 9);
    const samp = (L, n, u, v) => { const x = u * n, y = v * n, i = Math.floor(x), j = Math.floor(y), fx = x - i, fy = y - j; const sx = fx * fx * (3 - 2 * fx), sy = fy * fy * (3 - 2 * fy); const at = (a, b) => L[((b % n + n) % n) * n + ((a % n + n) % n)]; return lerp(lerp(at(i, j), at(i + 1, j), sx), lerp(at(i, j + 1), at(i + 1, j + 1), sx), sy); };
    for (let j = 0; j < DS; j++) for (let i = 0; i < DS; i++) {
      const u = i / DS, v = j / DS, k = (j * DS + i) * 4;
      const m = 0.55 * samp(L1, 16, u, v) + 0.45 * samp(L2, 48, u, v);
      const rd = 0.6 * samp(L3, 32, u, v) + 0.4 * samp(L4, 96, u, v);
      d[k] = 255 * clamp(0.5 + (m - 0.5) * 1.3, 0, 1); d[k + 1] = 255 * clamp(rd, 0, 1); d[k + 2] = 255 * clamp(0.35 + 0.65 * samp(L4, 96, u + 0.3, v + 0.7), 0, 1); d[k + 3] = 0;
    }
    // stubble: short dark hairs pointing down, drawn into alpha
    const sR = mulberry32(4242);
    const hairs = 1900;
    for (let n = 0; n < hairs; n++) {
      const x0 = sR() * DS, y0 = sR() * DS, ang = Math.PI / 2 + (sR() - 0.5) * 0.9, len = 2 + sR() * 5;
      const steps = Math.ceil(len * 2);
      for (let s = 0; s <= steps; s++) {
        const f = s / steps, x = Math.round(x0 + Math.cos(ang) * len * f), y = Math.round(y0 + Math.sin(ang) * len * f);
        const k = ((((y % DS) + DS) % DS) * DS + (((x % DS) + DS) % DS)) * 4;
        d[k + 3] = Math.max(d[k + 3], 255 * (0.95 - 0.5 * f));
      }
    }
    detailTex = new THREE.DataTexture(new Uint8Array(d.buffer), DS, DS);
  } else {
    normalTex = new THREE.DataTexture(new Uint8Array([128, 128, 255, 255]), 1, 1);
    detailTex = new THREE.DataTexture(new Uint8Array([128, 128, 128, 0]), 1, 1);
  }
  for (const t of [normalTex, detailTex]) {
    t.wrapS = t.wrapT = THREE.RepeatWrapping; t.magFilter = THREE.LinearFilter; t.minFilter = THREE.LinearMipmapLinearFilter; t.generateMipmaps = true; t.anisotropy = 4; t.needsUpdate = true;
  }
  DETAIL = { normal: normalTex, detail: detailTex };
  return DETAIL;
}

// ------------------------------------------------------------------ per-head feature maps (UV space)
export function featureMaps(D, P, sizeA, sizeH) {
  const F = D.F, RL = D.relief;
  const R = mulberry32((P.seed * 131 + 977) >>> 0);
  const uvOf = (p) => { const q = D.uvOfRef(p); return q; };
  const surf = (x, y) => [x, y, RL.M(x, y)];
  const cA = makeCanvas(sizeA, sizeA), cH = makeCanvas(sizeH, sizeH);
  if (!cA || !cH) return null;
  const A = cA.getContext('2d'), H = cH.getContext('2d', { willReadFrequently: true });
  const toPxA = (p) => { const q = uvOf(p); return [q[0] * sizeA, (1 - q[1]) * sizeA]; };
  const toPxH = (p) => { const q = uvOf(p); return [q[0] * sizeH, (1 - q[1]) * sizeH]; };
  const mmA = sizeA / 1024 * 3.6, mmH = sizeH / 512 * 1.8; // approx px per mm on the face
  A.clearRect(0, 0, sizeA, sizeA);
  H.fillStyle = 'rgb(128,128,128)'; H.fillRect(0, 0, sizeH, sizeH);
  A.lineCap = H.lineCap = 'round';
  const skin = hexLin(P.skin);
  const lumS = skin[0] * 0.2126 + skin[1] * 0.7152 + skin[2] * 0.0722;
  const grey = sstep(48, 70, P.age);
  // brow / lash colour: dark brown, greying with age, a little lighter on fair skin
  const hairC = [lerp(lerp(38, 62, sstep(0.25, 0.6, lumS)), 140, grey), lerp(lerp(26, 44, sstep(0.25, 0.6, lumS)), 136, grey), lerp(lerp(20, 32, sstep(0.25, 0.6, lumS)), 132, grey)];
  const rgba = (c, a) => `rgba(${Math.round(c[0])},${Math.round(c[1])},${Math.round(c[2])},${a})`;
  const strokeA = (pts, w, style) => { A.strokeStyle = style; A.lineWidth = w; A.beginPath(); pts.forEach((p, k) => { const q = toPxA(p); if (k) A.lineTo(q[0], q[1]); else A.moveTo(q[0], q[1]); }); A.stroke(); };
  const strokeH = (pts, w, style) => { H.strokeStyle = style; H.lineWidth = w; H.beginPath(); pts.forEach((p, k) => { const q = toPxH(p); if (k) H.lineTo(q[0], q[1]); else H.moveTo(q[0], q[1]); }); H.stroke(); };

  // ---- eyebrows: hair strokes following the brow shape (heavier and straighter for men)
  const fem = F.fem;
  const browW0 = lerp(8.2, 5.4, fem) * (1 + 0.15 * F.sh.brow), browW1 = lerp(2.6, 1.6, fem);
  const arch = lerp(1.2, 4.2, fem) - 1.2 * Math.max(0, F.sh.brow);
  for (const sd of [1, -1]) {
    const yb = F.yBrow;
    // brow centre line from head (medial) to tail (lateral), mm offsets from the brow landmark
    const line = (t) => { const x = lerp(0.0135, 0.0575, t); const yy = yb - 0.0022 + (arch * Math.sin(Math.PI * Math.min(1, t * 1.25)) - (t > 0.75 ? (t - 0.75) * 14 : 0)) * 0.001 - 0.0015 * F.frown * (1 - t); return [x, yy]; };
    const nH = Math.round(lerp(420, 300, fem) * (sizeA / 1024));
    // soft underlay
    for (let k = 0; k < 40; k++) { const t = k / 39, c = line(t), wmm = lerp(browW0, browW1, Math.pow(t, 1.3)); const p = toPxA(surf(sd * c[0], c[1])); A.fillStyle = rgba(hairC, 0.05); A.beginPath(); A.arc(p[0], p[1], wmm * 0.45 * mmA, 0, Math.PI * 2); A.fill(); }
    for (let n = 0; n < nH; n++) {
      const t = Math.pow(R(), 0.85), c = line(t), wmm = lerp(browW0, browW1, Math.pow(t, 1.3)) * 0.001;
      const off = (R() - 0.5) * wmm;
      const x0 = sd * c[0], y0 = c[1] + off;
      // direction: up at the head, sweeping laterally along the body, slightly down at the tail
      const ang = lerp(1.25, 0.12, sstep(0.0, 0.35, t)) - (t > 0.7 ? (t - 0.7) * 0.9 : 0) + (R() - 0.5) * 0.35 - off * 40;
      const len = (lerp(4.5, 7.5, R()) - 2.5 * t) * 0.001;
      const dx = sd * Math.cos(ang) * len, dy = Math.sin(ang) * len;
      const pts = [surf(x0, y0), surf(x0 + dx * 0.55, y0 + dy * 0.55 + 0.0003), surf(x0 + dx, y0 + dy - 0.0002 * len * 1000)];
      strokeA(pts, (0.75 + R() * 0.55) * mmA * 0.16, rgba(hairC.map(v => v * (0.7 + R() * 0.5)), 0.35 + R() * 0.4));
    }
  }
  // ---- lash lines (tight line along the lid margins)
  for (const E of D.eyes) {
    const up = E.upperA.map(p => p.map(v => v / D.S));
    if (up.length > 2) {
      strokeA(up, 0.75 * mmA, rgba([18, 13, 11], 0.85));
      // thicker toward the lateral end
      const lat = up.filter(p => E.side * (p[0] - E.lids.E[0]) > 0.003);
      if (lat.length > 2) strokeA(lat, 1.1 * mmA, rgba([16, 12, 10], 0.75));
    }
    const lo = E.lowerMargin.map(p => p.map(v => v / D.S));
    if (lo.length > 2) strokeA(lo, 0.45 * mmA, rgba([30, 22, 20], 0.38));
  }
  // ---- freckles and moles
  const nF = Math.round(380 * P.marks.freckles * (sizeA / 1024));
  for (let n = 0; n < nF; n++) {
    const x = (R() - 0.5) * 0.1 * Math.pow(R(), 0.6), y = F.yTip + R() * (F.yEye - F.yTip + 0.004) - 0.004;
    const p = toPxA(surf(x, y));
    A.fillStyle = rgba([skin[0] * 120, skin[1] * 70, skin[2] * 45].map(v => Math.min(255, v + 40)), 0.2 + R() * 0.3);
    A.beginPath(); A.ellipse(p[0], p[1], (0.3 + R() * 0.6) * mmA, (0.25 + R() * 0.5) * mmA, R() * 3, 0, Math.PI * 2); A.fill();
  }
  const nM = 1 + Math.floor(R() * 2.4);
  for (let n = 0; n < nM; n++) {
    const sd = R() < 0.5 ? 1 : -1;
    const x = sd * (0.02 + R() * 0.035), y = F.ySlit + R() * (F.yEye - F.ySlit);
    const p = toPxA(surf(x, y));
    A.fillStyle = rgba([60, 38, 28], 0.55); A.beginPath(); A.arc(p[0], p[1], (0.5 + R() * 0.5) * mmA, 0, Math.PI * 2); A.fill();
  }
  // ---- age spots
  if (F.old > 0.3) for (let n = 0; n < 10 * F.old; n++) {
    const x = (R() - 0.5) * 0.11, y = F.yEye + R() * 0.06;
    const p = toPxA(surf(x, y));
    A.fillStyle = rgba([110, 72, 50], 0.12 + 0.1 * R()); A.beginPath(); A.ellipse(p[0], p[1], (1 + R() * 2) * mmA, (0.8 + R() * 1.6) * mmA, R() * 3, 0, Math.PI * 2); A.fill();
  }

  // ---- wrinkle height field
  const W = F.wrinkles;
  const creaseH = (pts, wmm, depth) => { strokeH(pts, Math.max(1, wmm * mmH), `rgba(${Math.round(128 - depth)},${Math.round(128 - depth)},${Math.round(128 - depth)},1)`); };
  const yb = F.yBrow;
  // forehead lines
  const nFL = 3 + Math.round(2 * R());
  for (let k = 0; k < nFL; k++) {
    const y0 = yb + 0.011 + k * 0.0075 + (R() - 0.5) * 0.002;
    const pts = [];
    for (let q = 0; q <= 16; q++) { const x = (q / 16 - 0.5) * (0.075 - k * 0.006); pts.push(surf(x, y0 + 0.0012 * Math.sin(q * 0.7 + k * 2 + R()) - 0.004 * (x / 0.04) ** 2)); }
    creaseH(pts, 0.9, (8 + 34 * W) * (0.6 + 0.4 * R()));
  }
  // frown (glabellar) lines
  for (const sd of [1, -1]) {
    const pts = [surf(sd * 0.0055, yb - 0.004), surf(sd * 0.0062, yb + 0.004), surf(sd * 0.0072, yb + 0.012)];
    creaseH(pts, 0.8, (6 + 30 * F.frown) * (0.4 + W));
  }
  // crow's feet, under-eye lines
  for (const E of D.eyes) {
    const L = E.lids, sd = L.side, ex = L.E[0], ey = L.E[1];
    for (let k = 0; k < 4; k++) {
      const a = -0.45 + k * 0.32 + (R() - 0.5) * 0.15;
      const r0 = 0.0145, r1 = 0.026 + R() * 0.006;
      const pts = [];
      for (let q = 0; q <= 6; q++) { const r = lerp(r0, r1, q / 6); pts.push(surf(ex + sd * Math.cos(a) * r, ey + Math.sin(a) * r * 0.9 + 0.0008 * Math.sin(q))); }
      creaseH(pts, 0.7, (4 + 40 * W) * (0.5 + 0.5 * R()));
    }
    for (let k = 0; k < 2; k++) {
      const pts = [];
      for (let q = 0; q <= 8; q++) { const u = lerp(-0.006, 0.013, q / 8); pts.push(surf(ex + sd * u, ey - 0.0085 - k * 0.0028 - 0.0035 * (1 - ((u - 0.003) / 0.01) ** 2))); }
      creaseH(pts, 0.6, (3 + 26 * W) * (0.6 + 0.4 * R()));
    }
  }
  // lip vertical lines (always faint), stronger with age
  const mw = F.mouthW;
  for (let k = 0; k < 34; k++) {
    const x = (R() - 0.5) * 1.7 * mw, up = R() < 0.5;
    const sy = RL.slitY(x), h = up ? RL.tuF(x) : RL.tlF(x);
    if (h < 0.002) continue;
    const y0 = sy + (up ? 1 : -1) * h * 0.15, y1 = sy + (up ? 1 : -1) * h * (0.75 + 0.3 * R());
    creaseH([surf(x, y0), surf(x + (R() - 0.5) * 0.001, y1)], 0.5, 6 + 14 * W + 6 * R());
  }
  // nasolabial and marionette creases (age), neck lines
  if (W > 0.15) {
    for (const sd of [1, -1]) {
      creaseH([surf(sd * 0.0215 * F.noseW, F.ySub + 0.008), surf(sd * 0.026, F.ySub - 0.006), surf(sd * (mw + 0.006), F.ySlit + 0.003)], 1.0, 20 * W);
      if (F.old > 0.3) creaseH([surf(sd * mw * 1.05, F.ySlit - 0.003), surf(sd * mw * 1.13, F.ySlit - 0.02)], 0.9, 18 * F.old);
    }
  }
  for (let k = 0; k < 3; k++) {
    const y0 = -0.06 - k * 0.011;
    const pts = [];
    for (let q = 0; q <= 12; q++) { const a = (q / 12 - 0.5) * 1.9; const r = 0.056; pts.push([Math.sin(a) * r, y0 + 0.002 * Math.sin(q + k), -0.012 + Math.cos(a) * r * 1.05]); }
    creaseH(pts, 1.0, 4 + 24 * W);
  }
  // ---- scar (forehead into the brow, and the cheek, on the character's right side)
  if (P.marks.scar) {
    const segs = [
      [[-0.008, yb + 0.034], [-0.011, yb + 0.02], [-0.0135, yb + 0.006], [-0.016, yb - 0.004]],
      [[-0.038, F.yEye - 0.022], [-0.042, F.yEye - 0.031], [-0.046, F.yEye - 0.040]],
    ];
    for (const sg of segs) {
      const pts = sg.map(([x, y]) => surf(x, y));
      strokeA(pts, 2.2 * mmA, 'rgba(120,52,46,0.28)');
      strokeA(pts, 1.0 * mmA, 'rgba(214,150,140,0.55)');
      strokeA(pts, 0.45 * mmA, 'rgba(236,190,178,0.5)');
      strokeH(pts, 2.6 * mmH, 'rgba(110,110,110,1)');
      strokeH(pts, 0.9 * mmH, 'rgba(158,158,158,1)');
    }
  }
  // height -> normal
  const img = H.getImageData(0, 0, sizeH, sizeH).data;
  const h0 = new Float32Array(sizeH * sizeH), h = new Float32Array(sizeH * sizeH);
  for (let k = 0; k < sizeH * sizeH; k++) h0[k] = img[k * 4] / 255;
  for (let j = 0; j < sizeH; j++) for (let i = 0; i < sizeH; i++) {
    let s = 0, n = 0;
    for (let dj = -1; dj <= 1; dj++) { const jj = j + dj; if (jj < 0 || jj >= sizeH) continue; for (let di = -1; di <= 1; di++) { const ii = i + di; if (ii < 0 || ii >= sizeH) continue; const w = di === 0 && dj === 0 ? 4 : di === 0 || dj === 0 ? 2 : 1; s += h0[jj * sizeH + ii] * w; n += w; } }
    h[j * sizeH + i] = s / n;
  }
  const nd = heightToNormal(h, sizeH, sizeH, 5.5 * sizeH / 512, false, false);
  const normalTex = new THREE.DataTexture(nd, sizeH, sizeH);
  normalTex.flipY = false;
  normalTex.needsUpdate = true;
  normalTex.generateMipmaps = true; normalTex.minFilter = THREE.LinearMipmapLinearFilter; normalTex.magFilter = THREE.LinearFilter;
  // DataTexture rows start at v = 0; our canvas rows start at the top (v = 1): flip rows
  {
    const row = sizeH * 4, tmp = new Uint8Array(row);
    for (let j = 0; j < sizeH / 2; j++) { const a = j * row, b = (sizeH - 1 - j) * row; tmp.set(nd.subarray(a, a + row)); nd.copyWithin(a, b, b + row); nd.set(tmp, b); }
  }
  const albedoTex = new THREE.CanvasTexture(cA);
  albedoTex.colorSpace = THREE.SRGBColorSpace;
  albedoTex.anisotropy = 4;
  return { albedo: albedoTex, normal: normalTex };
}

// ------------------------------------------------------------------ material
export function createSkinMaterial(o) {
  const { base, featAlbedo, featNormal, detail, stubbleColor, sss = 1, thinScale = 1, detailTile = [1, 1], poreStrength = 0.55 } = o;
  const m = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color(base[0], base[1], base[2]), vertexColors: true,
    roughness: 1, metalness: 0, ior: 1.4, specularIntensity: 0.62,
    sheen: 0.22, sheenRoughness: 0.55, sheenColor: new THREE.Color(0.95, 0.72, 0.62),
    normalMap: featNormal || (detail ? detail.normal : null),
    normalScale: new THREE.Vector2(1, 1),
  });
  const U = {
    uPore: { value: detail ? detail.normal : null }, uDet: { value: detail ? detail.detail : null }, uFeat: { value: featAlbedo || null },
    uTile: { value: new THREE.Vector2(detailTile[0], detailTile[1]) }, uPoreStr: { value: poreStrength },
    uWrap: { value: new THREE.Vector3(0.5, 0.2, 0.12).multiplyScalar(sss) }, uStub: { value: new THREE.Color(...stubbleColor) },
    uThin: { value: thinScale },
  };
  m.userData.skinUniforms = U;
  const hasDet = !!detail, hasFeat = !!featAlbedo, hasN = !!(featNormal || detail);
  m.customProgramCacheKey = () => 'head_a_skin_' + hasDet + hasFeat + hasN;
  m.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, U);
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nattribute vec4 skinData;\nattribute vec2 uvd;\nvarying vec4 vSkin;\nvarying vec2 vUvd;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvSkin = skinData;\nvUvd = uvd;');
    let fs = sh.fragmentShader;
    fs = fs.replace('#include <common>', `#include <common>
      varying vec4 vSkin;
      varying vec2 vUvd;
      uniform sampler2D uPore; uniform sampler2D uDet; uniform sampler2D uFeat;
      uniform vec2 uTile; uniform float uPoreStr; uniform vec3 uWrap; uniform vec3 uStub; uniform float uThin;
      vec3 gSkinN = vec3(0.0, 0.0, 1.0);
      float gThin = 0.0;
      vec4 gDet = vec4(0.5);`);
    // albedo: detail mottling, stubble, painted features
    fs = fs.replace('#include <color_fragment>', `#include <color_fragment>
      #ifdef USE_NORMALMAP
        ${hasDet ? 'gDet = texture2D(uDet, vUvd * uTile);' : ''}
        diffuseColor.rgb *= 1.0 + (gDet.r - 0.5) * 0.22;
        diffuseColor.rgb *= 1.0 + (gDet.g - 0.5) * vec3(0.10, -0.03, -0.03);
        ${hasDet ? 'float stb = clamp(vSkin.z * gDet.a * 1.15, 0.0, 1.0); diffuseColor.rgb = mix(diffuseColor.rgb, uStub, stb * 0.92);' : ''}
        ${hasFeat ? 'vec4 ft = texture2D(uFeat, vNormalMapUv); diffuseColor.rgb = mix(diffuseColor.rgb, ft.rgb, ft.a);' : ''}
      #endif
      gThin = vSkin.w * uThin;`);
    fs = fs.replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
      roughnessFactor = clamp(vSkin.x * (0.86 + 0.28 * gDet.b) ${hasDet ? '+ 0.1 * vSkin.z * gDet.a' : ''}, 0.12, 0.95);`);
    fs = fs.replace('#include <normal_fragment_maps>', `gSkinN = normal;
      #include <normal_fragment_maps>`);
    if (hasDet) fs = fs.replace('mapN.xy *= normalScale;', `mapN.xy *= normalScale;
      { vec3 dN = texture2D(uPore, vUvd * uTile * 1.2).xyz * 2.0 - 1.0; mapN = normalize(vec3(mapN.xy + dN.xy * uPoreStr * vSkin.y, mapN.z)); }`);
    // subsurface approximation: per-channel wrap diffuse on a softened normal + thin-tissue transmission
    fs = fs.replace('reflectedLight.directDiffuse += irradiance * BRDF_Lambert( material.diffuseColor );', `{
        vec3 nD = normalize(mix(gSkinN, geometryNormal, 0.4));
        float nl = dot(nD, directLight.direction);
        vec3 w = uWrap;
        vec3 wi = clamp((vec3(nl) + w) / (1.0 + w), 0.0, 1.0);
        wi = mix(wi, wi * wi * (3.0 - 2.0 * wi), 0.35);
        float back = clamp(-dot(geometryNormal, directLight.direction), 0.0, 1.0);
        vec3 trans = gThin * vec3(0.9, 0.25, 0.12) * (0.25 + 0.75 * back) * 0.35;
        reflectedLight.directDiffuse += directLight.color * (wi + trans) * BRDF_Lambert( material.diffuseColor );
      }`);
    sh.fragmentShader = fs;
  };
  return m;
}
